mapper.select:
SELECT * FROM prj_quatation_elements pqe
1=1
and pqe.quotation_id = #{quotationId}

SELECT IF (
             @p = pqe.PROJECT_ID,
             @rank := @rank + 1 ,@rank := 1
         ) AS row_seq,
         @p := pqe.PROJECT_ID as rank1,
       pqe.*
FROM   prj_quatation_elements pqe,(SELECT @p := NULL ,@rank := 0) r

1=1

         and pqe.quotation_id = #{quotationId}


order by pqe.prj_elements_id
